"""Patches the Android project generated by `flutter create` for Doctori.

Run from the app/ folder after `flutter create --platforms=android .`:
  python3 tool/patch_android.py
Idempotent: safe to run on every build.
"""
import pathlib
import re
import sys

APP_ID = "com.doctori.app"
LABEL = "دكتوري"

manifest = pathlib.Path("android/app/src/main/AndroidManifest.xml")
text = manifest.read_text(encoding="utf-8")

permissions = """    <uses-permission android:name="android.permission.INTERNET"/>
    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION"/>
    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION"/>
"""
if "android.permission.INTERNET" not in text:
    text = re.sub(r"(<manifest[^>]*>\s*)", lambda m: m.group(1) + permissions, text, count=1)

text = re.sub(r'android:label="[^"]*"', f'android:label="{LABEL}"', text, count=1)

deep_link = f"""            <intent-filter>
                <action android:name="android.intent.action.VIEW"/>
                <category android:name="android.intent.category.DEFAULT"/>
                <category android:name="android.intent.category.BROWSABLE"/>
                <data android:scheme="{APP_ID}" android:host="login-callback"/>
            </intent-filter>
"""
if 'android:host="login-callback"' not in text:
    # Insert right after the MAIN/LAUNCHER intent-filter of MainActivity.
    text, n = re.subn(r"(<category android:name=\"android.intent.category.LAUNCHER\"\s*/>\s*</intent-filter>\s*)",
                      lambda m: m.group(1) + deep_link, text, count=1)
    if n != 1:
        sys.exit("Could not find the launcher intent-filter to add the deep link")

queries_extra = """        <intent>
            <action android:name="android.intent.action.VIEW"/>
            <data android:scheme="https"/>
        </intent>
        <intent>
            <action android:name="android.intent.action.DIAL"/>
            <data android:scheme="tel"/>
        </intent>
"""
if 'android:scheme="https"' not in text:
    if "<queries>" in text:
        text = text.replace("<queries>", "<queries>\n" + queries_extra, 1)
    else:
        text = text.replace("</manifest>", "    <queries>\n" + queries_extra + "    </queries>\n</manifest>", 1)

manifest.write_text(text, encoding="utf-8")

# applicationId → com.doctori.app (namespace stays as generated)
for name in ("android/app/build.gradle.kts", "android/app/build.gradle"):
    gradle = pathlib.Path(name)
    if gradle.exists():
        g = gradle.read_text(encoding="utf-8")
        g = re.sub(r'applicationId\s*=?\s*"[^"]+"',
                   lambda m: f'applicationId = "{APP_ID}"' if name.endswith(".kts") else f'applicationId "{APP_ID}"', g)
        gradle.write_text(g, encoding="utf-8")
        break
else:
    sys.exit("No app build.gradle found")

print("Android project patched for", APP_ID)
